package com.cryptoconnect.web;
import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){var errors=new HashMap<String,Object>();errors.put("timestamp",Instant.now());errors.put("error","Validation failed");errors.put("fields",e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->Objects.requireNonNullElse(x.getDefaultMessage(),"invalid"),(a,b)->a)));return ResponseEntity.badRequest().body(errors);} @ExceptionHandler(ResponseStatusException.class) ResponseEntity<Map<String,Object>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("timestamp",Instant.now(),"error",Objects.requireNonNullElse(e.getReason(),"Request failed")));} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Map<String,Object>> conflict(DataIntegrityViolationException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("timestamp",Instant.now(),"error","The request conflicts with an existing resource or data constraint"));} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> other(Exception e){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now(),"error","Internal server error"));} }
